package xyz.jovanstoiljkovic.isa.dtos.album;import xyz.jovanstoiljkovic.isa.dtos.BaseDTO;import xyz.jovanstoiljkovic.isa.dtos.artist.ArtistDTOLeaf;import xyz.jovanstoiljkovic.isa.dtos.comment.CommentDTOLeaf;import xyz.jovanstoiljkovic.isa.dtos.like.LikeDTOLeaf;import xyz.jovanstoiljkovic.isa.dtos.song.SongDTOLeaf;import xyz.jovanstoiljkovic.isa.dtos.tag.TagDTOLeaf;import xyz.jovanstoiljkovic.isa.models.*;import java.util.List;public class AlbumDTO extends BaseDTO<Album> {    private Long id;    private String name;    private ArtistDTOLeaf artist;    private List<SongDTOLeaf> songs;    private List<TagDTOLeaf> tags;    private List<LikeDTOLeaf> likes;    private List<CommentDTOLeaf> comments;    public AlbumDTO() {    }    public AlbumDTO(Long id, String name, ArtistDTOLeaf artist, List<SongDTOLeaf> songs, List<TagDTOLeaf> tags, List<LikeDTOLeaf> likes, List<CommentDTOLeaf> comments) {        this.id = id;        this.name = name;        this.artist = artist;        this.songs = songs;        this.tags = tags;        this.likes = likes;        this.comments = comments;    }    public Long getId() {        return id;    }    public void setId(Long id) {        this.id = id;    }    public String getName() {        return name;    }    public void setName(String name) {        this.name = name;    }    public ArtistDTOLeaf getArtist() {        return artist;    }    public void setArtist(ArtistDTOLeaf artist) {        this.artist = artist;    }    public List<SongDTOLeaf> getSongs() {        return songs;    }    public void setSongs(List<SongDTOLeaf> songs) {        this.songs = songs;    }    public List<TagDTOLeaf> getTags() {        return tags;    }    public void setTags(List<TagDTOLeaf> tags) {        this.tags = tags;    }    public List<LikeDTOLeaf> getLikes() {        return likes;    }    public void setLikes(List<LikeDTOLeaf> likes) {        this.likes = likes;    }    public List<CommentDTOLeaf> getComments() {        return comments;    }    public void setComments(List<CommentDTOLeaf> comments) {        this.comments = comments;    }}